#include<stdio.h>
 #include<string.h>
 int main(){
  char encrypted_pass[25] = "asdfxvnbkuj;knkj_asdfvdw";


  char user_input[25];
  // getting input from user redacted. assume user_input has been filled.
  int size;
  size = strlen(user_input);

  int x;
  int y;

  for (x=0; x < size; ++x){
  for (y=0; y < size; ++y){
  user_input[x] = user_input[x] << 1;
  user_input[x] = user_input[x] ^ (y+1);
